// Shared acceptance helpers, r2. The session log is the save record. Another task can import this module.
// No emulator behaviour change lives here.
// Do not edit this file after a runner that imports it has run.
import { createHash } from 'node:crypto';
import { readFileSync } from 'node:fs';

export const M_BYTES = 0x40000;
export const E_BYTES = 0x30000;

export function titleBand(frame) {
  const [w, h, words] = frame;
  const y1 = Math.max(1, Math.min(h, Math.floor(h * 0.16)));
  const x0 = Math.floor(w * 0.22);
  const x1 = Math.floor(w * 0.78);
  const buf = Buffer.alloc((x1 - x0) * y1 * 4);
  let o = 0;
  for (let y = 0; y < y1; y++) {
    for (let x = x0; x < x1; x++) {
      buf.writeUInt32LE(words[y * w + x] >>> 0, o);
      o += 4;
    }
  }
  return createHash('sha256').update(buf).digest('hex');
}

// Wait until the title band equals hash. On timeout throw Error with lastHash.
export function waitTitle(api, hash, timeoutMs) {
  const limit = api.labTime() + timeoutMs * 1e6;
  let frame = api.frame();
  if (!frame) throw new Error('screenshot failed before the title wait');
  let last = titleBand(frame);
  while (last !== hash && api.labTime() < limit) {
    api.idle(100);
    frame = api.frame();
    if (!frame) throw new Error('screenshot failed during the title wait');
    last = titleBand(frame);
  }
  if (last !== hash) {
    const err = new Error('title timeout, last ' + last);
    err.lastHash = last;
    err.expectedHash = hash;
    throw err;
  }
  return last;
}

// a and b are { M: Buffer, E: Buffer }. Every differing offset, both values.
export function compareStores(a, b) {
  const diffs = [];
  for (const bank of ['M', 'E']) {
    const left = a[bank];
    const right = b[bank];
    const n = Math.max(left.length, right.length);
    for (let i = 0; i < n; i++) {
      const av = i < left.length ? left[i] : null;
      const bv = i < right.length ? right[i] : null;
      if (av !== bv) diffs.push({ bank, offset: i, a: av, b: bv });
    }
  }
  return diffs;
}

// expected: { flag, zone, half: { cell: number[] }, mirror: { cell: number[] } }
// actual has the same fields, plus flagCached and zoneCached when present.
export function assertCells(actual, expected) {
  const problems = [];
  const exp = {};
  const got = {};
  if (expected.flag !== undefined) {
    exp.flag = expected.flag;
    got.flag = actual.flag;
    if (actual.flag !== expected.flag) problems.push('flag expected ' + expected.flag + ' actual ' + actual.flag);
    if (actual.flagCached !== undefined && actual.flagCached !== expected.flag) {
      problems.push('flag-cached expected ' + expected.flag + ' actual ' + actual.flagCached);
    }
  }
  if (expected.zone !== undefined) {
    exp.zone = expected.zone;
    got.zone = actual.zone;
    if (actual.zone !== expected.zone) problems.push('zone expected ' + expected.zone + ' actual ' + actual.zone);
    if (actual.zoneCached !== undefined && actual.zoneCached !== expected.zone) {
      problems.push('zone-cached expected ' + expected.zone + ' actual ' + actual.zoneCached);
    }
  }
  for (const group of ['half', 'mirror']) {
    if (!expected[group]) continue;
    exp[group] = expected[group];
    got[group] = {};
    for (const key of Object.keys(expected[group])) {
      const want = expected[group][key];
      const have = (actual[group] && actual[group][key]) || [];
      got[group][key] = have;
      for (let i = 0; i < want.length; i++) {
        if (have[i] !== want[i]) {
          problems.push(group + '.' + key + '[' + i + '] expected ' + want[i] + ' actual ' + have[i]);
        }
      }
    }
  }
  return { pass: problems.length === 0, problems, expected: exp, actual: got };
}

export function readStore(file) {
  const doc = JSON.parse(readFileSync(file, 'utf8'));
  return { M: Buffer.from(doc.M, 'base64'), E: Buffer.from(doc.E, 'base64') };
}

// Dirty the settings store the way a menu open then menu close does.
// api.press, api.step, api.saves() -> [{store, posted}], api.statuses (callback d0 values),
// api.saveHashes -> [{store, sha256}], api.nvramPath.
// Throws unless the log has M and E, every callback d0 is 0, and the file bytes match the images that were saved.
export function nativeSave(api) {
  const before = api.saves().length;
  const statusBefore = api.statuses.length;
  const hashBefore = api.saveHashes.length;
  const extra = api.saveExpect || {};
  api.press('menu');
  api.step('save-open', { ...extra, screen: 'menu' });
  api.press('menu');
  api.step('save-close', { ...extra, screen: 'shooting' });
  const added = api.saves();
  const reported = api.statuses.slice();
  const hashes = api.saveHashes.slice();
  const file = readStore(api.nvramPath);
  const problems = [];
  if (!added.some((x) => x.store === 'M')) problems.push('no-M');
  if (!added.some((x) => x.store === 'E')) problems.push('no-E');
  if (!reported.length) problems.push('no-callback');
  if (reported.some((s) => s !== 0)) problems.push('callback-status ' + reported.join(','));
  if (file.M.length !== M_BYTES) problems.push('M-bytes ' + file.M.length);
  if (file.E.length !== E_BYTES) problems.push('E-bytes ' + file.E.length);
  const fileHash = {
    M: createHash('sha256').update(file.M).digest('hex'),
    E: createHash('sha256').update(file.E).digest('hex'),
  };
  for (const bank of ['M', 'E']) {
    const seen = hashes.filter((h) => h.store === bank).at(-1);
    if (!seen) problems.push('no-image-' + bank);
    else if (seen.sha256 !== fileHash[bank]) problems.push('file-mismatch-' + bank);
  }
  const row = {
    added, reported, fileHash,
    hashes: hashes.map((h) => ({ store: h.store, sha256: h.sha256, posted: h.posted })),
    problems, mBytes: file.M.length, eBytes: file.E.length,
  };
  if (problems.length) {
    const err = new Error('nativeSave ' + problems.join('; '));
    err.row = row;
    throw err;
  }
  return { ...row, M: file.M, E: file.E };
}
